= []\n40\t\n41\tfunction projectNameFromCwd(cwd: string): string {\n42\t  const parts = cwd.split('/').filter(Boolean)\n43\t  return parts[parts.length - 1] || cwd\n44\t}\n45\t\n46\tfunction answerInEpic(epicId: string): void {\n47\t  setPendingPromptSessionId(epicId)\n48\t  window.dispatchEvent(new CustomEvent('sm:navigate', { detail: 'terminal' }))\n49\t}\n50\t\n51\tfunction PhNow({ cwd, snapshots }: { cwd: string; snapshots: EpicSnapshots }) {\n52\t  const cards = useMemo(() => inFlightCards(cwd, snapshots), [cwd, snapshots])\n53\t  return (\n54\t    <PhBlock kicker=\"now\" title=\"What is in flight\" note=\"Live from the Epic queue — this block is never hand-written.\">\n55\t      {cards.length === 0 ? (\n56\t        <p className=\"text-xs text-fg-faint\">No Epics in flight.</p>\n57\t      ) : (\n58\t        <div className=\"grid grid-cols-1 sm:grid-cols-3 gap-2.5\">\n59\t          {cards.map((card) => (\n60\t            <PhCard key={card.epicId} className=\"px-4 py-3.5 grid gap-1.5\">\n61\t              <EpicStatusChip status={card.status} small />\n62\t              <span className=\"text-sm font-semibold text-fg leading-tight\">{card.title}</span>\n63\t              <span className=\"text-xs text-fg-faint leading-relaxed\">{card.note}</span>\n64\t            </PhCard>\n65\t          ))}\n66\t        </div>\n67\t      )}\n68\t    </PhBlock>\n69\t  )\n70\t}\n71\t\n72\tfunction PhOpenQuestions({\n73\t  cwd,\n74\t  sessions,\n75\t  chats,\n76\t}: {\n77\t  cwd: string\n78\t  sessions: EpicSnapshots['sessions']\n79\t  chats: EpicSnapshots['chats']\n80\t}) {\n81\t  const questions = useMemo(() => openQuestions(cwd, sessions, chats), [cwd, sessions, chats])\n82\t  if (questions.length === 0) return null\n83\t  return (\n84\t    <PhBlock kicker=\"open\" title=\"Waiting on you\" note=\"Questions the last run could not resolve on its own.\">\n85\t      <div className=\"grid gap-2.5\">\n86\t        {questions.map((q) => (\n87\t          <div key={q.ticketId} className=\"rounded-xl border border-accent-dark/30 bg-accent/10 px-4 py-3.5\">\n88\t            <div className=\"text-sm text-fg leading-relaxed\">{q.question}</div>\n89\t            <div className=\"mt-2.5 flex items-center justify-between gap-3\">\n90\t              <span className=\"font-mono text-[10.5px] text-fg-faint\">Epic · {q.epicGoalText}</span>\n91\t              <button\n92\t                type=\"button\"\n93\t                onClick={() => answerInEpic(q.epicId)}\n94\t                className=\"shrink-0 rounded-md border border-line bg-bg-hi px-2.5 py-1 text-xs font-semibold text-fg-dim hover:text-fg\"\n95\t              >\n96\t                Answer in Epic →\n97\t              </button>\n98\t            </div>\n99\t          </div>\n100\t        ))}\n101\t      </div>\n102\t    </PhBlock>\n103\t  )\n104\t}\n105\t\n106\t// ── mini-markdown span renderer (PhMd) ────────────────────────────────────\n107\tfunction PhMd({ text }: { text: string }) {\n108\t  return (\n109\t    <>\n110\t      {tokenizeMd(text).map((tok, i) => {\n111\t        if (tok.type === 'bold') {\n112\t          return (\n113\t            <strong key={i} className=\"font-semibold text-fg\">\n114\t              {tok.text}\n115\t            </strong>\n116\t          )\n117\t        }\n118\t        if (tok.type === 'code') {\n119\t          return (\n120\t            <code key={i} className=\"font-mono text-[0.92em] bg-bg border border-rule rounded px-[5px] py-px\">\n121\t              {tok.text}\n122\t            </code>\n123\t          )\n124\t        }\n125\t        return <span key={i}>{tok.text}</span>\n126\t      })}\n127\t    </>\n128\t  )\n129\t}\n130\t\n131\t// ── header: identity + provenance + refresh ───────────────────────────────\n132\tfunction PhHeader({\n133\t  brief,\n134\t  sources,\n135\t  projectName,\n136\t  refreshing,\n137\t  onRefresh,\n138\t}: {\n139\t  brief: ProjectBrief | null\n140\t  sources: ProjectBriefSource[]\n141\t  projectName: string\n142\t  refreshing: boolean\n143\t  onRefresh: () => void\n144\t}) {\n145\t  const now = Date.now()\n146\t  return (\n147\t    <div className=\"rounded-xl border border-line bg-bg-hi px-6 py-5 mb-6\">\n148\t      <div className=\"flex items-start gap-4\">\n149\t        <div className=\"min-w-0\">\n150\t          <div className=\"font-mono text-[10px] font-semibold uppercase tracking-wide text-fg-faint mb-2\">\n151\t            The Brief\n152\t          </div>\n153\t          <h1 className=\"font-serif text-[26px] font-semibold text-fg leading-tight max-w-[760px]\">\n154\t            {brief?.purpose || projectName}\n155\t          </h1>\n156\t        </div>\n157\t        <div className=\"ml-auto text-right shrink-0\">\n158\t          <button\n159\t            type=\"button\"\n160\t            onClick={onRefresh}\n161\t            disabled={refreshing}\n162\t            className={`inline-flex items-center gap-1.5 rounded-lg px-3.5 py-2 text-xs font-semibold ${\n163\t              refreshing ? 'bg-accent-muted/60 text-fg-dim cursor-default' : 'bg-accent text-bg-hi cursor-pointer hover:bg-accent-dark'\n164\t            }`}\n165\t          >\n166\t            <span className={`inline-flex ${refreshing ? 'animate-spin' : ''}`}>\n167\t              <AlmanacIcon name=\"reload\" size={14} />\n168\t            </span>\n169\t            {refreshing ? 'Re-reading the project…' : 'Refresh brief'}\n170\t          </button>\n171\t          <div className=\"font-mono text-[10.5px] text-fg-faint mt-2 leading-relaxed\">\n172\t            {synthesizedAgoLabel(brief?.synthesizedAt, now)}\n173\t            {brief && (\n174\t              <>\n175\t                <br />\n176\t                by {brief.model}\n177\t              </>\n178\t            )}\n179\t          </div>\n180\t        </div>\n181\t      </div>\n182\t      {sources.length > 0 && (\n183\t        <div className=\"flex flex-wrap gap-1.5 mt-4 pt-3.5 border-t border-rule\">\n184\t          <span className=\"font-mono text-[10px] font-semibold uppercase tracking-wide text-fg-faint self-center mr-1\">\n185\t            read from\n186\t          </span>\n187\t          {sources.map((s) => {\n188\t            const chip = formatSourceChip(s)\n189\t            return (\n190\t              <span\n191\t                key={chip.label}\n192\t                className={`inline-flex items-center gap-1.5 bg-bg border rounded-full px-2.5 py-1 ${\n193\t                  chip.drift ? 'border-accent-dark/50' : 'border-rule'\n194\t                }`}\n195\t              >\n196\t                <span className=\"font-mono text-[11px] font-semibold text-fg-dim\">{chip.label}</span>\n197\t                <span className=\"text-[11px] text-fg-faint\">{chip.detail}</span>\n198\t                {chip.driftMark && (\n199\t                  <span className=\"font-mono text-[10px] font-semibold text-accent-dark\">{chip.driftMark}</span>\n200\t                )}\n201\t              </span>\n202\t            )\n203\t          })}\n204\t        </div>\n205\t      )}\n206\t    </div>\n207\t  )\n208\t}\n209\t\n210\tfunction PhWhat({ paragraphs, pinned, onPin }: { paragraphs: string[]; pinned: boolean; onPin: () => void }) {\n211\t  return (\n212\t    <PhBlock\n213\t      kicker=\"the project\"\n214\t      title=\"What this is\"\n215\t      pinned={pinned}\n216\t      onPin={onPin}\n217\t      note=\"Generated summary. Pin it once it reads right and refreshes will leave it alone.\"\n218\t    >\n219\t      <PhCard className=\"px-5 py-4 grid gap-3\">\n220\t        {paragraphs.map((p, i) => (\n221\t          <p key={i} className=\"text-sm leading-relaxed text-fg-dim max-w-[780px]\">\n222\t            <PhMd text={p} />\n223\t          </p>\n224\t        ))}\n225\t      </PhCard>\n226\t    </PhBlock>\n227\t  )\n228\t}\n229\t\n230\tfunction PhAreas({ areas }: { areas: ProjectBrief['areas'] }) {\n231\t  return (\n232\t    <PhBlock kicker=\"structure\" title=\"How it is put together\" note=\"Areas inferred from the tree and from which Epic has been editing them.\">\n233\t      <PhCard className=\"overflow-hidden\">\n234\t        {areas.map((a, i) => (\n235\t          <div\n236\t            key={a.name}\n237\t            className={`grid gap-4 items-center px-4 py-3 grid-cols-[minmax(0,1.5fr)_minmax(0,1.15fr)_116px] ${i > 0 ? 'border-t border-rule' : ''}`}\n238\t          >\n239\t            <span className=\"min-w-0\">\n240\t              <span className=\"flex items-baseline gap-2\">\n241\t                <span className=\"font-mono text-xs font-semibold text-fg\">{a.name}</span>\n242\t                <span className=\"font-mono text-[11px] text-fg-faint\">{a.files} files</span>\n243\t              </span>\n244\t              <span className=\"block text-xs text-fg-dim leading-relaxed mt-0.5\">{a.note}</span>\n245\t            </span>\n246\t            <span className={`min-w-0 text-xs leading-snug ${a.epic ? 'text-fg-dim' : 'text-fg-faint'}`}>\n247\t              {a.epic ? (\n248\t                <>\n249\t                  <span className=\"font-mono text-[10px] uppercase tracking-wide text-fg-faint block mb-0.5\">touched by</span>\n250\t                  {a.epic}\n251\t                </>\n252\t              ) : (\n253\t                <span className=\"font-mono text-[11px]\">no open Epic</span>\n254\t              )}\n255\t            </span>\n256\t            <span className=\"flex items-center gap-2\">\n257\t              <span className=\"flex-1 h-1.5 bg-bg border border-rule rounded-full overflow-hidden\">\n258\t                <span className=\"block h-full bg-accent/70\" style={{ width: `${heatPercent(a.heat)}%` }} />\n259\t              </span>\n260\t              <span className=\"font-mono text-[10.5px] text-fg-faint w-6 text-right\">{heatPercent(a.heat)}</span>\n261\t            </span>\n262\t          </div>\n263\t        ))}\n264\t      </PhCard>\n265\t    </PhBlock>\n266\t  )\n267\t}\n268\t\n269\tfunction PhScope({ scope }: { scope: ProjectBrief['scope'] }) {\n270\t  return (\n271\t    <PhBlock kicker=\"scope\" title=\"How the goal has moved\" note=\"Corrections and CLAUDE.md changes, newest first — the reason the brief above says what it says.\">\n272\t      <div className=\"grid\">\n273\t        {scope.map((s, i) => {\n274\t          const tone = scopeTone(s.kind)\n275\t          return (\n276\t            <div key={i} className=\"grid gap-3.5 items-start py-3 border-t border-rule grid-cols-[92px_84px_minmax(0,1fr)]\">\n277\t              <span className=\"font-mono text-[11px] text-fg-faint pt-0.5\">{s.when}</span>\n278\t              <span className={`font-mono text-[10px] font-semibold uppercase tracking-wide rounded border px-1.5 py-0.5 justify-self-start mt-px ${tone.textClass} ${tone.borderClass}`}>\n279\t                {tone.label}\n280\t              </span>\n281\t              <span>\n282\t                <span className=\"block text-sm text-fg leading-relaxed\">{s.text}</span>\n283\t                <span className=\"block font-mono text-[10.5px] text-fg-faint mt-1\">from {s.src}</span>\n284\t              </span>\n285\t            </div>\n286\t          )\n287\t        })}\n288\t      </div>\n289\t    </PhBlock>\n290\t  )\n291\t}\n292\t\n293\tfunction PhConventions({ conventions, pinned, onPin }: { conventions: string[]; pinned: boolean; onPin: () => void }) {\n294\t  return (\n295\t    <PhBlock\n296\t      kicker=\"rules\"\n297\t      title=\"Conventions Claude follows\"\n298\t      pinned={pinned}\n299\t      onPin={onPin}\n300\t      note=\"Mirrored from CLAUDE.md. Pinned, so a refresh cannot soften them.\"\n301\t    >\n302\t      <PhCard className=\"px-4 py-3.5 grid gap-2.5\">\n303\t        {conventions.map((c, i) => (\n304\t          <div key={i} className=\"grid grid-cols-[16px_minmax(0,1fr)] gap-2.5 items-start\">\n305\t            <span className=\"text-sage mt-0.5 inline-flex\">\n306\t              <AlmanacIcon name=\"check\" size={13} />\n307\t            </span>\n308\t            <span className=\"text-[13px] leading-relaxed text-fg-dim\">{c}</span>\n309\t          </div>\n310\t        ))}\n311\t      </PhCard>\n312\t    </PhBlock>\n313\t  )\n314\t}\n315\t\n316\texport function ProjectHome() {\n317\t  const tabs = useSessions((s) => s.tabs)\n318\t  const activeTabId = useSessions((s) => s.activeTabId)\n319\t  const activeTab = tabs.find((t) => t.id === activeTabId)\n320\t\n321\t  const sessions = usePromptSessions((s) => s.sessions)\n322\t  // Signal-level chats snapshot — a raw whole-map `useChat((s) => s.chats)`\n323\t  // subscription would re-render on every streaming token (PRD 833 I6).\n324\t  const chats = useChatSignals()\n325\t  const scheduleJobs = useScheduleState((s) => s.snapshot?.jobs) ?? EMPTY_JOBS\n326\t  const prds = useScheduledPrds()\n327\t\n328\t  const cwd = activeTab?.cwd ?? null\n329\t  useEffect(() => {\n330\t    if (!cwd) return\n331\t    void usePromptSessions.getState().hydrate(cwd)\n332\t    void usePromptSessions.getState().hydrateArchived(cwd)\n333\t  }, [cwd])\n334\t\n335\t  const [brief, setBrief] = useState<ProjectBrief | null>(null)\n336\t  const [sources, setSources] = useState<ProjectBriefSource[]>([])\n337\t  const [refreshing, setRefreshing] = useState(false)\n338\t\n339\t  const loadBrief = useCallback((targetCwd: string) => {\n340\t    let cancelled = false\n341\t    window.api.projectBrief\n342\t      .get(targetCwd)\n343\t      .then((res) => {\n344\t        if (cancelled) return\n345\t        setBrief(res.brief)\n346\t        setSources(res.sources)\n347\t      })\n348\t      .catch((err) => {\n349\t        if (cancelled) return\n350\t        toast.error(`Could not load the brief: ${err instanceof Error ? err.message : String(err)}`)\n351\t      })\n352\t    return () => {\n353\t      cancelled = true\n354\t    }\n355\t  }, [])\n356\t\n357\t  useEffect(() => {\n358\t    if (!cwd) return\n359\t    return loadBrief(cwd)\n360\t  }, [cwd, loadBrief])\n361\t\n362\t  const handleRefresh = useCallback(() => {\n363\t    if (!cwd || refreshing) return\n364\t    setRefreshing(true)\n365\t    window.api.projectBrief\n366\t      .refresh(cwd)\n367\t      .then((res) => {\n368\t        if (!res.ok) {\n369\t          toast.error(res.error)\n370\t          return\n371\t        }\n372\t        loadBrief(cwd)\n373\t      })\n374\t      .catch((err) => {\n375\t        toast.error(`Refresh failed: ${err instanceof Error ? err.message : String(err)}`)\n376\t      })\n377\t      .finally(() => setRefreshing(false))\n378\t  }, [cwd, refreshing, loadBrief])\n379\t\n380\t  const handlePin = useCallback(\n381\t    (block: ProjectBriefPinnableBlock) => {\n382\t      if (!cwd || !brief) return\n383\t      const nextPinned = !brief.pins?.[block]\n384\t      window.api.projectBrief\n385\t        .setPin(cwd, block, nextPinned)\n386\t        .then((res) => {\n387\t          if (!res.ok) {\n388\t            toast.error(res.error)\n389\t            return\n390\t          }\n391\t          setBrief(res.brief)\n392\t        })\n393\t        .catch((err) => {\n394\t          toast.error(`Could not pin the block: ${err instanceof Error ? err.message : String(err)}`)\n395\t        })\n396\t    },\n397\t    [cwd, brief],\n398\t  )\n399\t\n400\t  if (!activeTab) {\n401\t    return <EmptyState title=\"Open a project to see its brief\" />\n402\t  }\n403\t\n404\t  const projectName = projectNameFromCwd(activeTab.cwd)\n405\t  const snapshots: EpicSnapshots = { sessions, chats, jobs: scheduleJobs, prds }\n406\t\n407\t  return (\n408\t    <div className=\"h-full overflow-auto\">\n409\t      <div className=\"mx-auto max-w-[1080px] px-[34px] py-[26px] text-fg\">\n410\t        <PhHeader\n411\t          brief={brief}\n412\t          sources={sources}\n413\t          projectName={projectName}\n414\t          refreshing={refreshing}\n415\t          onRefresh={handleRefresh}\n416\t        />\n417\t\n418\t        {refreshing && (\n419\t          <div className=\"rounded-xl border border-accent-muted bg-accent-muted/20 px-4 py-2.5 mb-3.5 flex items-center gap-2.5 text-xs text-fg-dim\">\n420\t            <span className=\"inline-flex text-accent\">\n421\t              <AlmanacIcon name=\"sparkle\" size={14} />\n422\t            </span>\n423\t            A headless session is re-reading CLAUDE.md, the Epic archive and recent commits. Pinned blocks are left\n424\t            untouched.\n425\t          </div>\n426\t        )}\n427\t\n428\t        <PhNow cwd={activeTab.cwd} snapshots={snapshots} />\n429\t\n430\t        {brief ? (\n431\t          <>\n432\t            <PhWhat paragraphs={safeList(brief.what)} pinned={!!brief.pins?.what} onPin={() => handlePin('what')} />\n433\t            <PhAreas areas={safeList(brief.areas)} />\n434\t            <PhScope scope={safeList(brief.scope)} />\n435\t\n436\t            <div className=\"grid gap-3.5 grid-cols-1 lg:grid-cols-[minmax(0,1.05fr)_minmax(0,1fr)]\">\n437\t              <PhConventions\n438\t                conventions={safeList(brief.conventions)}\n439\t                pinned={!!brief.pins?.conventions}\n440\t                onPin={() => handlePin('conventions')}\n441\t              />\n442\t              <PhOpenQuestions cwd={activeTab.cwd} sessions={sessions} chats={chats} />\n443\t            </div>\n444\t\n445\t            <p className=\"text-xs text-fg-faint leading-relaxed max-w-[780px] mt-2\">\n446\t              The brief is regenerated by a headless session on demand. Pinned blocks are treated as source of truth\n447\t              and are fed back into the next synthesis instead of being rewritten.\n448\t            </p>\n449\t          </>\n450\t        ) : (\n451\t          <>\n452\t            <PhOpenQuestions cwd={activeTab.cwd} sessions={sessions} chats={chats} />\n453\t            <div className=\"py-10 flex flex-col items-center gap-3 text-center\">\n454\t              <p className=\"text-xs text-fg-faint max-w-sm\">\n455\t                No brief yet — generate one from CLAUDE.md, the Epic archive and recent commits.\n456\t              </p>\n457\t              <button\n458\t                type=\"button\"\n459\t                onClick={handleRefresh}\n460\t                disabled={refreshing}\n461\t                className={`inline-flex items-center gap-1.5 rounded-lg px-4 py-2 text-xs font-semibold ${\n462\t                  refreshing ? 'bg-accent-muted/60 text-fg-dim cursor-default' : 'bg-accent text-bg-hi cursor-pointer hover:bg-accent-dark'\n463\t                }`}\n464\t              >\n465\t                <span className={`inline-flex ${refreshing ? 'animate-spin' : ''}`}>\n466\t                  <AlmanacIcon name=\"reload\" size={14} />\n467\t                </span>\n468\t                {refreshing ? 'Re-reading the project…' : 'Generate the brief'}\n469\t              </button>\n470\t            </div>\n471\t          </>\n472\t        )}\n473\t      </div>\n474\t    </div>\n475\t  )\n476\t}\n477\t"}]},"uuid":"81d01b32-c508-4f9f-ad07-86dbbd0686f7","timestamp":"2026-08-01T05:19:54.801Z","toolUseResult":{"type":"text","file":{"filePath":"/home/bilko/Projects/session-manager/src/renderer/components/tabs/projecthome/ProjectHome.tsx","content":"/**\n * ProjectHome — \"The Brief\" for the active project (NavKey `project-home`).\n *\n * Renders PRD 837's backend (`window.api.projectBrief`) on top of PRD 839's\n * live Now/Waiting-on-you blocks: header card (purpose, refresh, provenance\n * chips), the synthesized What/Structure/Scope/Conventions blocks, and the\n * no-brief-yet \"Generate the brief\" empty state — same code path as Refresh.\n */\n\nimport { useCallback, useEffect, useMemo, useState } from 'react'\nimport { useSessions } from '../../../state/sessions'\nimport { usePromptSessions } from '../../../state/promptSessions'\nimport { useChatSignals } from '../../../lib/useChatSignals'\nimport { useScheduleState } from '../../../state/scheduleState'\nimport { useScheduledPrds } from '../../../lib/useScheduledPrds'\nimport { inFlightCards, openQuestions } from '../../../lib/projectHomeDerive'\nimport { setPendingPromptSessionId } from '../../../lib/promptSessionDeepLink'\nimport {\n  formatSourceChip,\n  heatPercent,\n  safeList,\n  scopeTone,\n  synthesizedAgoLabel,\n  tokenizeMd,\n} from '../../../lib/projectBriefView'\nimport type { EpicSnapshots } from '../../../lib/epicDerive'\nimport type {\n  ProjectBrief,\n  ProjectBriefPinnableBlock,\n  ProjectBriefSource,\n  ScheduleJob,\n} from '../../../../preload/api'\nimport { EpicStatusChip } from '../../epics/epic-primitives'\nimport { AlmanacIcon } from '../../layout/AlmanacIcon'\nimport { EmptyState } from '../../ui/EmptyState'\nimport { toast } from '../../../state/toast'\nimport { PhBlock, PhCard } from './ph-primitives'\n\nconst EMPTY_JOBS: ScheduleJob[] = []\n\nfunction projectNameFromCwd(cwd: string): string {\n  const parts = cwd.split('/').filter(Boolean)\n  return parts[parts.length - 1] || cwd\n}\n\nfunction answerInEpic(epicId: string): void {\n  setPendingPromptSessionId(epicId)\n  window.dispatchEvent(new CustomEvent('sm:navigate', { detail: 'terminal' }))\n}\n\nfunction PhNow({ cwd, snapshots }: { cwd: string; snapshots: EpicSnapshots }) {\n  const cards = useMemo(() => inFlightCards(cwd, snapshots), [cwd, snapshots])\n  return (\n    <PhBlock kicker=\"now\" title=\"What is in flight\" note=\"Live from the Epic queue — this block is never hand-written.\">\n      {cards.length === 0 ? (\n        <p className=\"text-xs text-fg-faint\">No Epics in flight.</p>\n      ) : (\n        <div className=\"grid grid-cols-1 sm:grid-cols-3 gap-2.5\">\n          {cards.map((card) => (\n            <PhCard key={card.epicId} className=\"px-4 py-3.5 grid gap-1.5\">\n              <EpicStatusChip status={card.status} small />\n              <span className=\"text-sm font-semibold text-fg leading-tight\">{card.title}</span>\n              <span className=\"text-xs text-fg-faint leading-relaxed\">{card.note}</span>\n            </PhCard>\n          ))}\n        </div>\n      )}\n    </PhBlock>\n  )\n}\n\nfunction PhOpenQuestions({\n  cwd,\n  sessions,\n  chats,\n}: {\n  cwd: string\n  sessions: EpicSnapshots['sessions']\n  chats: EpicSnapshots['chats']\n}) {\n  const questions = useMemo(() => openQuestions(cwd, sessions, chats), [cwd, sessions, chats])\n  if (questions.length === 0) return null\n  return (\n    <PhBlock kicker=\"open\" title=\"Waiting on you\" note=\"Questions the last run could not resolve on its own.\">\n      <div className=\"grid gap-2.5\">\n        {questions.map((q) => (\n          <div key={q.ticketId} className=\"rounded-xl border border-accent-dark/30 bg-accent/10 px-4 py-3.5\">\n            <div className=\"text-sm text-fg leading-relaxed\">{q.question}</div>\n            <div className=\"mt-2.5 flex items-center justify-between gap-3\">\n              <span className=\"font-mono text-[10.5px] text-fg-faint\">Epic · {q.epicGoalText}</span>\n              <button\n                type=\"button\"\n                onClick={() => answerInEpic(q.epicId)}\n                className=\"shrink-0 rounded-md border border-line bg-bg-hi px-2.5 py-1 text-xs font-semibold text-fg-dim hover:text-fg\"\n              >\n                Answer in Epic →\n              </button>\n            </div>\n          </div>\n        ))}\n      </div>\n    </PhBlock>\n  )\n}\n\n// ── mini-markdown span renderer (PhMd) ────────────────────────────────────\nfunction PhMd({ text }: { text: string }) {\n  return (\n    <>\n      {tokenizeMd(text).map((tok, i) => {\n        if (tok.type === 'bold') {\n          return (\n            <strong key={i} className=\"font-semibold text-fg\">\n              {tok.text}\n            </strong>\n          )\n        }\n        if (tok.type === 'code') {\n          return (\n            <code key={i} className=\"font-mono text-[0.92em] bg-bg border border-rule rounded px-[5px] py-px\">\n              {tok.text}\n            </code>\n          )\n        }\n        return <span key={i}>{tok.text}</span>\n      })}\n    </>\n  )\n}\n\n// ── header: identity + provenance + refresh ───────────────────────────────\nfunction PhHeader({\n  brief,\n  sources,\n  projectName,\n  refreshing,\n  onRefresh,\n}: {\n  brief: ProjectBrief | null\n  sources: ProjectBriefSource[]\n  projectName: string\n  refreshing: boolean\n  onRefresh: () => void\n}) {\n  const now = Date.now()\n  return (\n    <div className=\"rounded-xl border border-line bg-bg-hi px-6 py-5 mb-6\">\n      <div className=\"flex items-start gap-4\">\n        <div className=\"min-w-0\">\n          <div className=\"font-mono text-[10px] font-semibold uppercase tracking-wide text-fg-faint mb-2\">\n            The Brief\n          </div>\n          <h1 className=\"font-serif text-[26px] font-semibold text-fg leading-tight max-w-[760px]\">\n            {brief?.purpose || projectName}\n          </h1>\n        </div>\n        <div className=\"ml-auto text-right shrink-0\">\n          <button\n            type=\"button\"\n            onClick={onRefresh}\n            disabled={refreshing}\n            className={`inline-flex items-center gap-1.5 rounded-lg px-3.5 py-2 text-xs font-semibold ${\n              refreshing ? 'bg-accent-muted/60 text-fg-dim cursor-default' : 'bg-accent text-bg-hi cursor-pointer hover:bg-accent-dark'\n            }`}\n          >\n            <span className={`inline-flex ${refreshing ? 'animate-spin' : ''}`}>\n              <AlmanacIcon name=\"reload\" size={14} />\n            </span>\n            {refreshing ? 'Re-reading the project…' : 'Refresh brief'}\n          </button>\n          <div className=\"font-mono text-[10.5px] text-fg-faint mt-2 leading-relaxed\">\n            {synthesizedAgoLabel(brief?.synthesizedAt, now)}\n            {brief && (\n              <>\n                <br />\n                by {brief.model}\n              </>\n            )}\n          </div>\n        </div>\n      </div>\n      {sources.length > 0 && (\n        <div className=\"flex flex-wrap gap-1.5 mt-4 pt-3.5 border-t border-rule\">\n          <span className=\"font-mono text-[10px] font-semibold uppercase tracking-wide text-fg-faint self-center mr-1\">\n            read from\n          </span>\n          {sources.map((s) => {\n            const chip = formatSourceChip(s)\n            return (\n              <span\n                key={chip.label}\n                className={`inline-flex items-center gap-1.5 bg-bg border rounded-full px-2.5 py-1 ${\n                  chip.drift ? 'border-accent-dark/50' : 'border-rule'\n                }`}\n              >\n                <span className=\"font-mono text-[11px] font-semibold text-fg-dim\">{chip.label}</span>\n                <span className=\"text-[11px] text-fg-faint\">{chip.detail}</span>\n                {chip.driftMark && (\n                  <span className=\"font-mono text-[10px] font-semibold text-accent-dark\">{chip.driftMark}</span>\n                )}\n              </span>\n            )\n          })}\n        </div>\n      )}\n    </div>\n  )\n}\n\nfunction PhWhat({ paragraphs, pinned, onPin }: { paragraphs: string[]; pinned: boolean; onPin: () => void }) {\n  return (\n    <PhBlock\n      kicker=\"the project\"\n      title=\"What this is\"\n      pinned={pinned}\n      onPin={onPin}\n      note=\"Generated summary. Pin it once it reads right and refreshes will leave it alone.\"\n    >\n      <PhCard className=\"px-5 py-4 grid gap-3\">\n        {paragraphs.map((p, i) => (\n          <p key={i} className=\"text-sm leading-relaxed text-fg-dim max-w-[780px]\">\n            <PhMd text={p} />\n          </p>\n        ))}\n      </PhCard>\n    </PhBlock>\n  )\n}\n\nfunction PhAreas({ areas }: { areas: ProjectBrief['areas'] }) {\n  return (\n    <PhBlock kicker=\"structure\" title=\"How it is put together\" note=\"Areas inferred from the tree and from which Epic has been editing them.\">\n      <PhCard className=\"overflow-hidden\">\n        {areas.map((a, i) => (\n          <div\n            key={a.name}\n            className={`grid gap-4 items-center px-4 py-3 grid-cols-[minmax(0,1.5fr)_minmax(0,1.15fr)_116px] ${i > 0 ? 'border-t border-rule' : ''}`}\n          >\n            <span className=\"min-w-0\">\n              <span className=\"flex items-baseline gap-2\">\n                <span className=\"font-mono text-xs font-semibold text-fg\">{a.name}</span>\n                <span className=\"font-mono text-[11px] text-fg-faint\">{a.files} files</span>\n              </span>\n              <span className=\"block text-xs text-fg-dim leading-relaxed mt-0.5\">{a.note}</span>\n            </span>\n            <span className={`min-w-0 text-xs leading-snug ${a.epic ? 'text-fg-dim' : 'text-fg-faint'}`}>\n              {a.epic ? (\n                <>\n                  <span className=\"font-mono text-[10px] uppercase tracking-wide text-fg-faint block mb-0.5\">touched by</span>\n                  {a.epic}\n                </>\n              ) : (\n                <span className=\"font-mono text-[11px]\">no open Epic</span>\n              )}\n            </span>\n            <span className=\"flex items-center gap-2\">\n              <span className=\"flex-1 h-1.5 bg-bg border border-rule rounded-full overflow-hidden\">\n                <span className=\"block h-full bg-accent/70\" style={{ width: `${heatPercent(a.heat)}%` }} />\n              </span>\n              <span className=\"font-mono text-[10.5px] text-fg-faint w-6 text-right\">{heatPercent(a.heat)}</span>\n            </span>\n          </div>\n        ))}\n      </PhCard>\n    </PhBlock>\n  )\n}\n\nfunction PhScope({ scope }: { scope: ProjectBrief['scope'] }) {\n  return (\n    <PhBlock kicker=\"scope\" title=\"How the goal has moved\" note=\"Corrections and CLAUDE.md changes, newest first — the reason the brief above says what it says.\">\n      <div className=\"grid\">\n        {scope.map((s, i) => {\n          const tone = scopeTone(s.kind)\n          return (\n            <div key={i} className=\"grid gap-3.5 items-start py-3 border-t border-rule grid-cols-[92px_84px_minmax(0,1fr)]\">\n              <span className=\"font-mono text-[11px] text-fg-faint pt-0.5\">{s.when}</span>\n              <span className={`font-mono text-[10px] font-semibold uppercase tracking-wide rounded border px-1.5 py-0.5 justify-self-start mt-px ${tone.textClass} ${tone.borderClass}`}>\n                {tone.label}\n              </span>\n              <span>\n                <span className=\"block text-sm text-fg leading-relaxed\">{s.text}</span>\n                <span className=\"block font-mono text-[10.5px] text-fg-faint mt-1\">from {s.src}</span>\n              </span>\n            </div>\n          )\n        })}\n      </div>\n    </PhBlock>\n  )\n}\n\nfunction PhConventions({ conventions, pinned, onPin }: { conventions: string[]; pinned: boolean; onPin: () => void }) {\n  return (\n    <PhBlock\n      kicker=\"rules\"\n      title=\"Conventions Claude follows\"\n      pinned={pinned}\n      onPin={onPin}\n      note=\"Mirrored from CLAUDE.md. Pinned, so a refresh cannot soften them.\"\n    >\n      <PhCard className=\"px-4 py-3.5 grid gap-2.5\">\n        {conventions.map((c, i) => (\n          <div key={i} className=\"grid grid-cols-[16px_minmax(0,1fr)] gap-2.5 items-start\">\n            <span className=\"text-sage mt-0.5 inline-flex\">\n              <AlmanacIcon name=\"check\" size={13} />\n            </span>\n            <span className=\"text-[13px] leading-relaxed text-fg-dim\">{c}</span>\n          </div>\n        ))}\n      </PhCard>\n    </PhBlock>\n  )\n}\n\nexport function ProjectHome() {\n  const tabs = useSessions((s) => s.tabs)\n  const activeTabId = useSessions((s) => s.activeTabId)\n  const activeTab = tabs.find((t) => t.id === activeTabId)\n\n  const sessions = usePromptSessions((s) => s.sessions)\n  // Signal-level chats snapshot — a raw whole-map `useChat((s) => s.chats)`\n  // subscription would re-render on every streaming token (PRD 833 I6).\n  const chats = useChatSignals()\n  const scheduleJobs = useScheduleState((s) => s.snapshot?.jobs) ?? EMPTY_JOBS\n  const prds = useScheduledPrds()\n\n  const cwd = activeTab?.cwd ?? null\n  useEffect(() => {\n    if (!cwd) return\n    void usePromptSessions.getState().hydrate(cwd)\n    void usePromptSessions.getState().hydrateArchived(cwd)\n  }, [cwd])\n\n  const [brief, setBrief] = useState<ProjectBrief | null>(null)\n  const [sources, setSources] = useState<ProjectBriefSource[]>([])\n  const [refreshing, setRefreshing] = useState(false)\n\n  const loadBrief = useCallback((targetCwd: string) => {\n    let cancelled = false\n    window.api.projectBrief\n      .get(targetCwd)\n      .then((res) => {\n        if (cancelled) return\n        setBrief(res.brief)\n        setSources(res.sources)\n      })\n      .catch((err) => {\n        if (cancelled) return\n        toast.error(`Could not load the brief: ${err instanceof Error ? err.message : String(err)}`)\n      })\n    return () => {\n      cancelled = true\n    }\n  }, [])\n\n  useEffect(() => {\n    if (!cwd) return\n    return loadBrief(cwd)\n  }, [cwd, loadBrief])\n\n  const handleRefresh = useCallback(() => {\n    if (!cwd || refreshing) return\n    setRefreshing(true)\n    window.api.projectBrief\n      .refresh(cwd)\n      .then((res) => {\n        if (!res.ok) {\n          toast.error(res.error)\n          return\n        }\n        loadBrief(cwd)\n      })\n      .catch((err) => {\n        toast.error(`Refresh failed: ${err instanceof Error ? err.message : String(err)}`)\n      })\n      .finally(() => setRefreshing(false))\n  }, [cwd, refreshing, loadBrief])\n\n  const handlePin = useCallback(\n    (block: ProjectBriefPinnableBlock) => {\n      if (!cwd || !brief) return\n      const nextPinned = !brief.pins?.[block]\n      window.api.projectBrief\n        .setPin(cwd, block, nextPinned)\n        .then((res) => {\n          if (!res.ok) {\n            toast.error(res.error)\n            return\n          }\n          setBrief(res.brief)\n        })\n        .catch((err) => {\n          toast.error(`Could not pin the block: ${err instanceof Error ? err.message : String(err)}`)\n        })\n    },\n    [cwd, brief],\n  )\n\n  if (!activeTab) {\n    return <EmptyState title=\"Open a project to see its brief\" />\n  }\n\n  const projectName = projectNameFromCwd(activeTab.cwd)\n  const snapshots: EpicSnapshots = { sessions, chats, jobs: scheduleJobs, prds }\n\n  return (\n    <div className=\"h-full overflow-auto\">\n      <div className=\"mx-auto max-w-[1080px] px-[34px] py-[26px] text-fg\">\n        <PhHeader\n          brief={brief}\n          sources={sources}\n          projectName={projectName}\n          refreshing={refreshing}\n          onRefresh={handleRefresh}\n        />\n\n        {refreshing && (\n          <div className=\"rounded-xl border border-accent-muted bg-accent-muted/20 px-4 py-2.5 mb-3.5 flex items-center gap-2.5 text-xs text-fg-dim\">\n            <span className=\"inline-flex text-accent\">\n              <AlmanacIcon name=\"sparkle\" size={14} />\n            </span>\n            A headless session is re-reading CLAUDE.md, the Epic archive and recent commits. Pinned blocks are left\n            untouched.\n          </div>\n        )}\n\n        <PhNow cwd={activeTab.cwd} snapshots={snapshots} />\n\n        {brief ? (\n          <>\n            <PhWhat paragraphs={safeList(brief.what)} pinned={!!brief.pins?.what} onPin={() => handlePin('what')} />\n            <PhAreas areas={safeList(brief.areas)} />\n            <PhScope scope={safeList(brief.scope)} />\n\n            <div className=\"grid gap-3.5 grid-cols-1 lg:grid-cols-[minmax(0,1.05fr)_minmax(0,1fr)]\">\n              <PhConventions\n                conventions={safeList(brief.conventions)}\n                pinned={!!brief.pins?.conventions}\n                onPin={() => handlePin('conventions')}\n              />\n              <PhOpenQuestions cwd={activeTab.cwd} sessions={sessions} chats={chats} />\n            </div>\n\n            <p className=\"text-xs text-fg-faint leading-relaxed max-w-[780px] mt-2\">\n              The brief is regenerated by a headless session on demand. Pinned blocks are treated as source of truth\n              and are fed back into the next synthesis instead of being rewritten.\n            </p>\n          </>\n        ) : (\n          <>\n            <PhOpenQuestions cwd={activeTab.cwd} sessions={sessions} chats={chats} />\n            <div className=\"py-10 flex flex-col items-center gap-3 text-center\">\n              <p className=\"text-xs text-fg-faint max-w-sm\">\n                No brief yet — generate one from CLAUDE.md, the Epic archive and recent commits.\n              </p>\n              <button\n                type=\"button\"\n                onClick={handleRefresh}\n                disabled={refreshing}\n                className={`inline-flex items-center gap-1.5 rounded-lg px-4 py-2 text-xs font-semibold ${\n                  refreshing ? 'bg-accent-muted/60 text-fg-dim cursor-default' : 'bg-accent text-bg-hi cursor-pointer hover:bg-accent-dark'\n                }`}\n              >\n                <span className={`inline-flex ${refreshing ? 'animate-spin' : ''}`}>\n                  <AlmanacIcon name=\"reload\" size={14} />\n                </span>\n                {refreshing ? 'Re-reading the project…' : 'Generate the brief'}\n              </button>\n            </div>\n          </>\n        )}\n      </div>\n    </div>\n  )\n}\n","numLines":477,"startLine":1,"totalLines":477}},"sourceToolAssistantUUID":"79bbbe53-1e0c-43f7-893a-75c09b973775","session_id":"c8d2ca66-6317-4c69-9461-dbbdad3aee58","userType":"external","entrypoint":"cli","cwd":"/home/bilko/Projects/session-manager","sessionId":"c8d2ca66-6317-4c69-9461-dbbdad3aee58","version":"2.1.220","gitBranch":"main"}
