   <AlmanacIcon name=\"star\" size={12} />\n38\t              </button>\n39\t            )}\n40\t          </div>\n41\t          <h2 className=\"font-serif text-xl font-semibold text-fg leading-tight\">{title}</h2>\n42\t          {note && <p className=\"mt-1 text-xs text-fg-faint leading-relaxed\">{note}</p>}\n43\t        </div>\n44\t        {right && <span className=\"ml-auto pb-0.5 shrink-0\">{right}</span>}\n45\t      </div>\n46\t      {children}\n47\t    </section>\n48\t  )\n49\t}\n50\t\n51\texport function PhCard({ children, className = '' }: { children: ReactNode; className?: string }) {\n52\t  return <div className={`rounded-xl border border-line bg-bg-hi ${className}`}>{children}</div>\n53\t}\n54\t"}]},"uuid":"8d82f4b9-4f8c-4f68-bed0-a6714302c26c","timestamp":"2026-08-01T05:21:13.373Z","toolUseResult":{"type":"text","file":{"filePath":"/home/bilko/Projects/session-manager/src/renderer/components/tabs/projecthome/ph-primitives.tsx","content":"/**\n * Shared block chrome for ProjectHome (\"The Brief\") sections — mono uppercase\n * accent kicker + serif h2 + faint note line, translated from the mock's\n * `PhBlock` (project-home-mock.jsx) to Tailwind Almanac tokens. Status pills\n * reuse `components/epics/epic-primitives.tsx` rather than the mock's own\n * hex `PH_ST` map.\n */\nimport type { ReactNode } from 'react'\nimport { AlmanacIcon } from '../../layout/AlmanacIcon'\n\ninterface PhBlockProps {\n  kicker: string\n  title: string\n  note?: string\n  children: ReactNode\n  /** Pinnable blocks (What this is / Conventions): current pin state + toggle handler. */\n  pinned?: boolean\n  onPin?: () => void\n  /** Optional content flush-right of the kicker/title column (unused today, mirrors the mock's `right` slot). */\n  right?: ReactNode\n}\n\nexport function PhBlock({ kicker, title, note, children, pinned, onPin, right }: PhBlockProps) {\n  return (\n    <section className=\"mb-7\">\n      <div className=\"mb-3 flex items-end gap-3.5\">\n        <div className=\"min-w-0\">\n          <div className=\"flex items-center gap-2 mb-1\">\n            <span className=\"font-mono text-[10px] font-semibold uppercase tracking-wide text-accent\">{kicker}</span>\n            {onPin && (\n              <button\n                type=\"button\"\n                onClick={onPin}\n                title={pinned ? 'Pinned — refreshes will not overwrite this' : 'Pin so refreshes leave it alone'}\n                className={`inline-flex ${pinned ? 'text-accent' : 'text-fg-faint opacity-45 hover:opacity-70'}`}\n              >\n                <AlmanacIcon name=\"star\" size={12} />\n              </button>\n            )}\n          </div>\n          <h2 className=\"font-serif text-xl font-semibold text-fg leading-tight\">{title}</h2>\n          {note && <p className=\"mt-1 text-xs text-fg-faint leading-relaxed\">{note}</p>}\n        </div>\n        {right && <span className=\"ml-auto pb-0.5 shrink-0\">{right}</span>}\n      </div>\n      {children}\n    </section>\n  )\n}\n\nexport function PhCard({ children, className = '' }: { children: ReactNode; className?: string }) {\n  return <div className={`rounded-xl border border-line bg-bg-hi ${className}`}>{children}</div>\n}\n","numLines":54,"startLine":1,"totalLines":54}},"sourceToolAssistantUUID":"db18ec57-bb17-40a0-b038-eeb466cd7962","session_id":"c8d2ca66-6317-4c69-9461-dbbdad3aee58","userType":"external","entrypoint":"cli","cwd":"/home/bilko/Projects/session-manager","sessionId":"c8d2ca66-6317-4c69-9461-dbbdad3aee58","version":"2.1.220","gitBranch":"main"}
