: { detail: '1 line', mtimeMs: 999 },\n44\t    epics: null,\n45\t    sessions: null,\n46\t    git: null,\n47\t  });\n48\t  assert.equal(sources[0].drift, false);\n49\t});\n50\t\n51\ttest('buildSynthesisPrompt includes CLAUDE.md, epics, git log, tree, and pinned block instruction', () => {\n52\t  const prompt = buildSynthesisPrompt({\n53\t    claudeMdText: '# Project X',\n54\t    epics: [{ status: 'active', tag: 'feature', goalText: 'Ship the thing' }],\n55\t    gitLogLines: ['abc123 fix bug'],\n56\t    srcTree: 'src/\\n  main/\\n  renderer/',\n57\t    pinnedBlocks: { conventions: ['Never use shell:true'] },\n58\t  });\n59\t  assert.match(prompt, /# Project X/);\n60\t  assert.match(prompt, /Ship the thing/);\n61\t  assert.match(prompt, /abc123 fix bug/);\n62\t  assert.match(prompt, /src\\/\\n  main\\//);\n63\t  assert.match(prompt, /PINNED BLOCK \"conventions\"/);\n64\t  assert.match(prompt, /Never use shell:true/);\n65\t  assert.doesNotMatch(prompt, /PINNED BLOCK \"what\"/);\n66\t});\n67\t\n68\ttest('validateBriefShape: accepts a well-formed object, rejects malformed ones', () => {\n69\t  const good = { purpose: 'x', what: [], areas: [], scope: [], conventions: [] };\n70\t  assert.deepEqual(validateBriefShape(good), { ok: true, error: null });\n71\t  assert.equal(validateBriefShape(null).ok, false);\n72\t  assert.equal(validateBriefShape({ ...good, purpose: '' }).ok, false);\n73\t  assert.equal(validateBriefShape({ ...good, what: 'not an array' }).ok, false);\n74\t  assert.equal(validateBriefShape({ ...good, areas: undefined }).ok, false);\n75\t});\n76\t\n77\ttest('applyPinEnforcement: overwrites a pinned block with the frozen copy, carries pins/pinned forward', () => {\n78\t  const raw = { purpose: 'p', what: ['fresh what'], areas: [], scope: [], conventions: ['fresh conventions'] };\n79\t  const priorPins = { what: false, conventions: true };\n80\t  const priorPinned = { what: null, conventions: ['frozen conventions'] };\n81\t  const merged = applyPinEnforcement(r