es = computeSetPin(brief, 'areas', true);\n121\t  assert.equal(res.ok, false);\n122\t});\n123\t\n124\ttest('computeSetPin: pinning freezes current block content, unpinning clears it', () => {\n125\t  const brief = {\n126\t    purpose: 'p',\n127\t    what: ['a', 'b'],\n128\t    areas: [],\n129\t    scope: [],\n130\t    conventions: ['c1'],\n131\t    pins: { what: false, conventions: false },\n132\t    pinned: { what: null, conventions: null },\n133\t  };\n134\t  const pinned = computeSetPin(brief, 'what', true);\n135\t  assert.equal(pinned.ok, true);\n136\t  assert.equal(pinned.brief.pins.what, true);\n137\t  assert.deepEqual(pinned.brief.pinned.what, ['a', 'b']);\n138\t\n139\t  const unpinned = computeSetPin(pinned.brief, 'what', false);\n140\t  assert.equal(unpinned.ok, true);\n141\t  assert.equal(unpinned.brief.pins.what, false);\n142\t  assert.equal(unpinned.brief.pinned.what, null);\n143\t});\n144\t\n145\t// ── computeUpdate: the hand-edit (\"maintain\") path ────────────────────────\n146\tfunction baseBrief() {\n147\t  return {\n148\t    version: 1,\n149\t    synthesizedAt: '2026-07-31T00:00:00.000Z',\n150\t    editedAt: null,\n151\t    model: 'sonnet',\n152\t    purpose: 'p',\n153\t    what: ['a'],\n154\t    areas: [{ name: 'x', files: 1, note: '', epic: null, heat: 0.1 }],\n155\t    scope: [],\n156\t    conventions: ['c1'],\n157\t    pins: { what: false, conventions: false },\n158\t    pinned: { what: null, conventions: null },\n159\t  };\n160\t}\n161\t\n162\ttest('computeUpdate: errors when there is no brief yet', () => {\n163\t  const res = computeUpdate(null, { what: ['x'] }, '2026-08-01T00:00:00.000Z');\n164\t  assert.equal(res.ok, false);\n165\t  assert.match(res.error, /generate one first/);\n166\t});\n167\t\n168\ttest('computeUpdate: rejects an empty patch and non-editable fields', () => {\n169\t  assert.equal(computeUpdate(baseBrief(), {}, 'NOW').ok, false);\n170\t  const res = computeUpdate(baseBrief(), { model: 'opus' }, 'NOW');\n171\t  assert.equal(res.ok, false);\n172\t  assert.match(res.error, /not editable: model/);\n173\t});\n174\t\n175\ttest('computeUpdate: rejects field shapes the renderer could not render', () => {\n176\t  assert.equal(computeUpdate(baseBrief(), { purpose: '   ' }, 'NOW').ok, false);\n177\t  assert.equal(computeUpdate(baseBrief(), { what: 'not an array' }, 'NOW').ok, false);\n178\t  assert.equal(computeUpdate(baseBrief(), { conventions: [1, 2] }, 'NOW').ok, false);\n179\t  assert.equal(computeUpdate(baseBrief(), { areas: ['nope'] }, 'NOW').ok, false);\n180\t});\n181\t\n182\ttest('computeUpdate: applies the patch, stamps editedAt, leaves other fields alone', () => {\n183\t  const before = baseBrief();\n184\t  const res = computeUpdate(before, { purpose: 'sharper' }, '2026-08-01T00:00:00.000Z');\n\n... [32 lines truncated] ..."},"type":"attachment","uuid":"6ed8f680-8f3a-44d5-b05d-16bf5198eafd","timestamp":"2026-08-01T05:24:23.682Z","session_id":"c8d2ca66-6317-4c69-9461-dbbdad3aee58","userType":"external","entrypoint":"cli","cwd":"/home/bilko/Projects/session-manager","sessionId":"c8d2ca66-6317-4c69-9461-dbbdad3aee58","version":"2.1.220","gitBranch":"main"}
