{"parentUuid":"134b281f-daef-49ae-a08f-db4af53072ec","isSidechain":false,"promptId":"b1b9c97b-80cb-4059-bdfc-a0e31f46cf3e","type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01GADT85ZGix48Q6o5Pb6umn","type":"tool_result","content":"/**\n * Shared presentational primitives for the Almanac Scheduler design.\n * Single source of truth consumed by Queue / PRDs / History restyle PRDs (20-group).\n */\nimport type { ReactNode } from 'react'\nimport type { ScheduleJobStatus } from '../../../../preload/api'\nimport { projectColorFor } from '../../../lib/projectColor'\n\n// ─── projectNameFromCwd — canonical \"last path segment\" extraction ──────────\n// Single source for turning an absolute project cwd into a short display\n// name. Consumed by ProjectTag below plus every filter/list/group surface in\n// this family that needs to match or list projects by name (Queue filter\n// text search, History's project dropdown + filter, PRDs card list).\nexport function projectNameFromCwd(cwd?: string | null): string | null {\n  if (!cwd) return null\n  const segs = cwd.replace(/\\/+$/, '').split('/')\n  return segs[segs.length - 1] || cwd\n}\n\nfunction projectDot(cwd?: string | null, name?: string): string {\n  const base = cwd ? (projectNameFromCwd(cwd) ?? '') : (name ?? '')\n  return projectColorFor(base)\n}\n\n// ─── SchBadge ────────────────────────────────────────────────────────────────\nconst BADGE_CLASSES: Record<ScheduleJobStatus, string> = {\n  running:      'bg-accent text-white',\n  pending:      'bg-bg text-fg-dim border border-line',\n  completed:    'bg-sage/20 text-sage',\n  needs_review: 'bg-butter/25 text-fg-dim',\n    </span>\n  )\n}\n\n// ─── ProjectTag ──────────────────────────────────────────────────────────────\nexport function ProjectTag({ cwd, name }: { cwd?: string | null; name?: string }) {\n  const label = name ?? (cwd ? projectNameFromCwd(cwd) ?? cwd : '—')\n  const dot = projectDot(cwd, name)\n  return (\n    <span className=\"inline-flex items-center gap-1.5 font-mono text-xs text-fg-faint\">\n      <span\n        className=\"w-1.5 h-1.5 rounded-full shrink-0\"\n        style={{ backgroundColor: dot }}\n        aria-hidden=\"true\"\n      />\n      {label}\n    </span>\n  )\n}\n\n// ─── DetailBlock / DetailLine ────────────────────────────────────────────────\nexport function DetailBlock({ label, children }: { label: string; children: ReactNode }) {\n  return (\n    <div>\n      <div className=\"text-[11px] font-bold tracking-[0.7px] uppercase text-fg-faint mb-2\">\n        {label}\n=== SchedulePanel 775-880 ===\n\n  // Traceability link back to the PromptSession this job's PRD was authored\n  // from (see promptSessionDeepLink.ts) — job.sourceTabId equals a\n  // PromptSession's own id when the PRD came out of PromptSessionConversation\n  // (its chat key IS the PromptSession id), so a match here is the PRD → the\n  // goal-scoped conversation that spawned it, for tracing + reopening it to\n  // see the completion prompt the scheduler published back into that session.\n  const linkedPromptSession = usePromptSessions((s) =>\n    job.sourceTabId ? (s.sessions[job.sourceTabId] ?? null) : null,\n  )\n\n  const navigateToPromptSession = useCallback((id: string) => {\n    setPendingPromptSessionId(id)\n    window.dispatchEvent(new CustomEvent('sm:navigate', { detail: 'terminal' }))\n  }, [])\n\n  const isRunning = job.status === 'running'\n  const isFailed = job.status === 'failed'\n\n  let trailingLabel: string | null = null\n  if (isRunning && job.startedAt) {\n    trailingLabel = `${formatDuration(now - Date.parse(job.startedAt))} elapsed`\n  } else if (job.status === 'completed' && job.startedAt && job.finishedAt) {\n    trailingLabel = `took ${formatTimingLabel(Date.parse(job.finishedAt) - Date.parse(job.startedAt))}`\n  } else if (eta) {\n    trailingLabel = eta\n  }\n\n  // Note shown in collapsed row below the title\n  const errorText = job.error ?? null\n  const note = isFailed && errorText\n    ? errorText.split('\\n')[0]\n    : job.status === 'needs_review' && job.verifierVerdict\n      ? verdictLabel(job.verifierVerdict)\n      : null\n\n  // Progress fraction for running jobs (capped at 0.99 so it never \"completes\")\n  const progressPct = isRunning && job.startedAt\n    ? Math.min(0.99, (now - Date.parse(job.startedAt)) / avgDurationMs)\n    : 0\n\n  return (\n    <div\n      role=\"listitem\"\n      className=\"border-t border-line\"\n    >\n      <button\n        type=\"button\"\n        data-job-row\n        data-job-index={listIndex}\n        onClick={() => setOpen((v) => !v)}\n        onFocus={() => onFocused(listIndex)}\n        className={`w-full text-left grid grid-cols-[116px_1fr_auto_auto] items-center gap-4 px-[18px] py-3.5 hover:bg-bg/40 focus:outline-none focus:ring-1 focus:ring-accent focus:ring-inset ${open ? 'bg-bg-elev/40' : ''}`}\n        aria-expanded={open}\n        aria-label={`${prdNumber(job.slug) ? `PRD ${prdNumber(job.slug)}, ` : ''}${job.title}, ${job.status}${trailingLabel ? `, ${trailingLabel}` : ''}`}\n        title={job.title}\n      >\n        <SchBadge status={job.status} />\n        <div className=\"min-w-0\">\n          <div className=\"flex items-baseline gap-2 text-[14.5px] font-medium text-fg leading-snug\">\n            {prdNumber(job.slug) && <PrdNumberBadge n={prdNumber(job.slug)!} />}\n            {job.title}\n          </div>\n          {note && (\n            <div className={`text-[12.5px] mt-0.5 ${isFailed ? 'text-accent/80' : 'text-fg-faint'}`}>\n              {note}\n            </div>\n          )}\n          {linkedPromptSession ? (\n            <span\n              role=\"button\"\n              tabIndex={0}\n              data-testid=\"job-row-prompt-session-chip\"\n              title={linkedPromptSession.goalText}\n              onClick={(e) => {\n                e.stopPropagation()\n                e.preventDefault()\n                navigateToPromptSession(linkedPromptSession.id)\n              }}\n              onKeyDown={(e) => {\n                if (e.key === 'Enter' || e.key === ' ') {\n                  e.stopPropagation()\n                  e.preventDefault()\n                  navigateToPromptSession(linkedPromptSession.id)\n                }\n              }}\n              className=\"inline-block mt-0.5 text-[12.5px] text-accent hover:text-accent/80 cursor-pointer truncate max-w-full\"\n            >\n              {truncateLabel(linkedPromptSession.goalText) || linkedPromptSession.id.slice(0, 8)}\n            </span>\n          ) : (job.sourcePromptId || job.sourceTabId) ? (\n            <span\n              data-testid=\"job-row-prompt-session-chip\"\n              title=\"Source prompt session is not currently loaded\"\n              className=\"inline-block mt-0.5 text-[12.5px] text-fg-faint truncate max-w-full\"\n            >\n              {(job.sourcePromptId ?? job.sourceTabId ?? '').slice(0, 8)}\n            </span>\n          ) : null}\n        </div>\n        <ProjectTag cwd={job.cwd} />\n        <span className=\"inline-flex items-center gap-2.5 font-mono text-xs text-fg-faint shrink-0\">\n          {trailingLabel}\n          <span\n            className={`text-fg-faint inline-flex transition-transform duration-150 ${open ? 'rotate-90' : ''}`}\n            aria-hidden=\"true\"","is_error":false}]},"uuid":"5979745a-4b7c-4b2b-bb25-efec934590e1","timestamp":"2026-08-01T05:47:52.734Z","toolUseResult":{"stdout":"/**\n * Shared presentational primitives for the Almanac Scheduler design.\n * Single source of truth consumed by Queue / PRDs / History restyle PRDs (20-group).\n */\nimport type { ReactNode } from 'react'\nimport type { ScheduleJobStatus } from '../../../../preload/api'\nimport { projectColorFor } from '../../../lib/projectColor'\n\n// ─── projectNameFromCwd — canonical \"last path segment\" extraction ──────────\n// Single source for turning an absolute project cwd into a short display\n// name. Consumed by ProjectTag b