h active project's <cwd>/session-manager-operations/scheduler/prds/\n30\t * files. One surface, no duplication.\n31\t */\n32\t\n33\ttype SubView = 'queue' | 'prds' | 'history'\n34\t\n35\tconst LS_KEY = 'sm.schedulerTab.subView'\n36\t\n37\tconst VIEW_OPTIONS = [\n38\t  { key: 'queue' as const, label: 'Queue' },\n39\t  { key: 'prds' as const, label: 'PRDs' },\n40\t  { key: 'history' as const, label: 'History' },\n41\t]\n42\t\n43\tfunction isToday(isoStr: string, nowMs: number): boolean {\n44\t  const d = new Date(isoStr)\n45\t  const t = new Date(nowMs)\n46\t  return d.getFullYear() === t.getFullYear() && d.getMonth() === t.getMonth() && d.getDate() === t.getDate()\n47\t}\n48\t\n49\t// ─── Window status strip ─────────────────────────────────────────────────────\n50\t\n51\tfunction pauseMessage(reason: string, resumeAt: string | null, now: number): string {\n52\t  if (reason === 'auth') {\n53\t    return 'Scheduler paused: Claude sign-in expired or invalid. Restart the app or re-run `claude login`, then Resume.'\n54\t  }\n55\t  if (reason === 'rate_limit') {\n56\t    if (resumeAt) {\n57\t      const ms = new Date(resumeAt).getTime()\n58\t      const remaining = ms - now\n59\t      if (remaining > 0) {\n60\t        return `Paused for rate limit — resumes in ${formatRelative(remaining)}`\n61\t      }\n62\t      return 'Paused for rate limit — resume pending'\n63\t    }\n64\t    return 'Paused for rate limit'\n65\t  }\n66\t  if (reason === 'network') {\n67\t    return 'Paused: billing endpoint unreachable for 30+ min.'\n68\t  }\n69\t  if (reason === 'manual') {\n70\t    return 'Scheduler paused manually. Click Resume to restart.'\n71\t  }\n72\t  return `Scheduler paused (${reason})`\n73\t}\n74\t\n75\tfunction WindowStrip({ scopeCwd }: { scopeCwd: string | null }) {\n76\t  const { snapshot } = useScheduleState()\n77\t  const [now, setNow] = useState(() => Date.now())\n78\t\n79\t  useEffect(() => {\n80\t    const id = setInterval(() => setNow(Date.now()), 30_000)\n81\t    return () => clearInterval(id)\n82\t  }, [])\n83\t\n84\t  if (!snapshot) return null\n85\t\n86\t  // Job counts follow the scope toggle so the strip agrees with the list\n87\t  // rendered directly beneath it. The reset countdown, utilization and\n88\t  // last-batch readings below stay machine-wide on purpose — they describe the\n89\t  // 5h billing window and the scheduler tick, not this project's work.\n90\t  const jobs = (snapshot.jobs ?? []).filter(j => !scopeCwd || j.cwd === scopeCwd)\n91\t  const pending   = jobs.filter(j => j.status === 'pending').length\n92\t  const running   = jobs.filter(j => j.status === 'running').length\n93\t  const completed = jobs.filter(j => j.status === 'completed' && (j.finishedAt ? isToday(j.finishedAt, now) : false)).length\n94\t\n95\t  const nextResetMs = snapshot.nextReset ? new Date(snapshot.nextReset).getTime() : null\n96\t  const resetsIn = nextResetMs\n97\t    ? (nextResetMs > now ? formatRelative(nextResetMs - now) : 'soon')\n98\t    : '—'\n99\t\n100\t  const lastBatch = formatAgo(\n101\t    snapshot.lastRunAt ? new Date(snapshot.lastRunAt).getTime() : null,\n102\t    now,\n103\t  )\n104\t\n105\t  const paused = snapshot.paused\n106\t  const pollHealth = snapshot.pollHealth\n107\t  const pollStale = pollHealth != null && !pollHealth.lastPollOk\n108\t\n109\t  const isErrorPause = paused?.reason === 'auth' || paused?.reason === 'network'\n110\t  const pauseBannerClass = isErrorPause\n111\t    ? 'bg-red-950/60 border-red-700/50 text-red-200'\n112\t    : 'bg-amber-950/60 border-amber-700/50 text-amber-200'\n113\t\n114\t  return (\n115\t    <div className=\"flex flex-col gap-2\">\n116\t      {/* Pause banner — only when paused */}\n117\t      {paused && (\n118\t        <div className={`flex items-center gap-3 border rounded-xl px-4 py-2.5 text-[13px] ${pauseBannerClass}`}>\n119\t          <span className=\"flex-1 leading-snug\">\n120\t            {pauseMessage(paused.reason, paused.resumeAt, now)}\n121\t          </span>\n122\t          <button\n123\t            type=\"button\"\n124\t            onClick={() => window.api.schedule.resume()}\n125\t            className=\"shrink-0 px-2.5 py-1 rounded border border-current/40 hover:bg-white/10 transition-colors text-[12px] font-medium\"\n126\t          >\n127\t            Resume\n128\t          </button>\n129\t        </div>\n130\t      )}\n131\t\n132\t      {/* Stats row */}\n133\t      <div className=\"flex items-center gap-5 flex-wrap bg-bg-hi border border-line rounded-xl px-4 py-3\">\n134\t        {/* Reset countdown */}\n135\t        <span className=\"inline-flex items-center gap-2 text-[13.5px] text-fg font-semibold whitespace-nowrap\">\n136\t          <span className=\"text-sage\" aria-hidden=\"true\">\n137\t            <AlmanacIcon name=\"clock\" size={15} />\n138\t          </span>\n139\t          Window resets in {resetsIn}\n140\t        </span>\n141\t\n142\t        <span className=\"w-px h-[18px] bg-rule shrink-0\" aria-hidden=\"true\" />\n143\t\n144\t        {/* Job legend */}\n145\t        <LegendItem dotClass=\"bg-fg-faint\" n={pending}   label=\"pending\" />\n146\t        <LegendItem dotClass=\"bg-accent\"   n={running}   label=\"running\" />\n147\t        <LegendItem dotClass=\"bg-sage\"     n={completed} label=\"completed today\" />\n148\t\n149\t        {/* Utilization — stale indicator when polls are failing */}\n150\t        {snapshot.utilization !== null && snapshot.utilization !== undefined && (\n151\t          <>\n152\t            <span className=\"w-px h-[18px] bg-rule shrink-0\" aria-hidden=\"true\" />\n153\t            {pollStale ? (\n154\t              <span className=\"font-mono text-[12.5px] text-amber-400/70\" title=\"Billing poll failing — this reading may be outdated\">\n155\t                {Math.round(snapshot.utilization)}% of window used · last good reading{' '}\n156\t                {formatAgo(pollHealth!.lastPollAt, now)}\n157\t              </span>\n158\t            ) : (\n159\t              <span class