{"parentUuid":"6bdd48dd-8ab5-4614-a53a-2f3d61150e63","isSidechain":false,"attachment":{"type":"edited_text_file","filename":"/home/bilko/Projects/session-manager/src/renderer/components/tabs/scheduler/sched-primitives.tsx","snippet":"1\t/**\n2\t * Shared presentational primitives for the Almanac Scheduler design.\n3\t * Single source of truth consumed by Queue / PRDs / History restyle PRDs (20-group).\n4\t */\n5\timport type { ReactNode } from 'react'\n6\timport type { ScheduleJobStatus } from '../../../../preload/api'\n7\timport { projectColorFor } from '../../../lib/projectColor'\n8\timport { shortEpicId } from '../../../lib/epicProvenance'\n9\t\n10\t// ─── projectNameFromCwd — canonical \"last path segment\" extraction ──────────\n11\t// Single source for turning an absolute project cwd into a short display\n12\t// name. Consumed by ProjectTag below plus every filter/list/group surface in\n13\t// this family that needs to match or list projects by name (Queue filter\n14\t// text search, History's project dropdown + filter, PRDs card list).\n15\texport function projectNameFromCwd(cwd?: string | null): string | null {\n16\t  if (!cwd) return null\n17\t  const segs = cwd.replace(/\\/+$/, '').split('/')\n18\t  return segs[segs.length - 1] || cwd\n19\t}\n20\t\n21\tfunction projectDot(cwd?: string | null, name?: string): string {\n22\t  const base = cwd ? (projectNameFromCwd(cwd) ?? '') : (name ?? '')\n23\t  return projectColorFor(base)\n24\t}\n25\t\n26\t// ─── SchBadge ────────────────────────────────────────────────────────────────\n27\tconst BADGE_CLASSES: Record<ScheduleJobStatus, string> = {\n28\t  running:      'bg-accent text-white',\n29\t  pending:      'bg-bg text-fg-dim border border-line',\n30\t  completed:    'bg-sage/20 text-sage',\n31\t  needs_review: 'bg-butter/25 text-fg-dim',\n32\t  failed:       'bg-accent/15 text-accent',\n33\t}\n34\t\n35\tconst BADGE_MARKS: Partial<Record<ScheduleJobStatus, string>> = {\n36\t  pending:      '○',\n37\t  completed:    '✓',\n38\t  needs_review: '!',\n39\t  failed:       '✕',\n40\t}\n41\t\n42\texport function SchBadge({ status }: { status: ScheduleJobStatus }) {\n43\t  const mark = BADGE_MARKS[status]\n44\t  return (\n45\t    <span\n46\t      className={`inline-flex items-center gap-1.5 shrink-0 px-2.5 py-1 rounded-lg min-w-[104px] justify-center text-xs font-semibold tracking-wide ${BADGE_CLASSES[status]}`}\n47\t      role=\"status\"\n48\t      aria-label={`Status: ${status.replace('_', ' ')}`}\n49\t    >\n50\t      {status === 'running' ? (\n51\t        <span className=\"w-1.5 h-1.5 rounded-full bg-white animate-pulse\" aria-hidden=\"true\" />\n52\t      ) : (\n53\t        mark && <span aria-hidden=\"true\">{mark}</span>\n54\t      )}\n55\t      {status.replace('_', ' ')}\n56\t    </span>\n57\t  )\n58\t}\n59\t\n60\t// ─── ProjectTag ──────────────────────────────────────────────────────────────\n61\texport function ProjectTag({ cwd, name }: { cwd?: string | null; name?: string }) {\n62\t  const label = name ?? (cwd ? projectNameFromCwd(cwd) ?? cwd : '—')\n63\t  const dot = projectDot(cwd, name)\n64\t  return (\n65\t    <span className=\"inline-flex items-center gap-1.5 font-mono text-xs text-fg-faint\">\n66\t      <span\n67\t        className=\"w-1.5 h-1.5 rounded-full shrink-0\"\n68\t        style={{ backgroundColor: dot }}\n69\t        aria-hidden=\"true\"\n70\t      />\n71\t      {label}\n72\t    </span>\n73\t  )\n74\t}\n75\t\n76\t// ─── EpicTag ─────────────────────────────────────────────────────────────────\n77\t// \"Which Epic did this come from\" — the one chip every Scheduler surface uses\n78\t// (Queue rows, PRD cards, History rows) so they can't drift apart. Purely\n79\t// presentational, like ProjectTag: the caller resolves the ref via\n80\t// lib/epicProvenance.resolveEpicRef and passes the result in. `onOpen` makes\n81\t// it a deep-link into the Epic; omit it for a static label.\n82\texport function EpicTag({\n83\t  epicId,\n84\t  label,\n85\t  onOpen,\n86\t  testId = 'epic-tag',\n87\t  className = '',\n88\t}: {\n89\t  epicId: string | null\n90\t  label: string | null\n91\t  onOpen?: (epicId: string) => void\n92\t  /** Overridable so a host row can keep its own established test hook. */\n93\t  testId?: string\n94\t  className?: string\n95\t}) {\n96\t  if (!epicId) return null\n97\t  const known = label != null\n98\t  const text = known ? label : shortEpicId(epicId)\n99\t  const title = known ? `Epic · ${label}` : `Epic ${epicId} is not currently loaded`\n100\t  const body = (\n101\t    <>\n102\t      <span className=\"text-[10px] font-semibold uppercase tracking-wide opacity-70 shrink-0\">epic</span>\n103\t      <span className=\"truncate\">{text}</span>\n104\t    </>\n105\t  )\n106\t  const base = `inline-flex items-center gap-1.5 font-mono text-[11.5px] max-w-full min-w-0 ${className}`\n107\t  if (!onOpen || !known) {\n108\t    return (\n109\t      <span data-testid={testId} data-epic-id={epicId} title={title} className={`${base} text-fg-faint`}>\n110\t        {body}\n111\t      </span>\n112\t    )\n113\t  }\n114\t  return (\n115\t    <span\n116\t      role=\"button\"\n117\t      tabIndex={0}\n118\t      data-testid={testId}\n119\t      data-epic-id={epicId}\n120\t      title={title}\n121\t      onClick={(e) => {\n122\t        e.stopPropagation()\n123\t        e.preventDefault()\n124\t        onOpen(epicId)\n125\t      }}\n126\t      onKeyDown={(e) => {\n127\t        if (e.key === 'Enter' || e.key === ' ') {\n128\t          e.stopPropagation()\n129\t          e.preventDefault()\n130\t          onOpen(epicId)\n131\t        }\n132\t      }}\n133\t      className={`${base} text-accent hover:text-accent/80 cursor-pointer`}\n134\t    >\n135\t      {body}\n136\t    </span>\n137\t  )\n138\t}\n139\t\n140\t// ─── DetailBlock / DetailLine ────────────────────────────────────────────────\n141\texport function DetailBlock({ label, children }: { label: string; children: ReactNode }) {\n142\t  return (\n143\t    <div>\n144\t      <div className=\"text-[11px] font-bold tracking-[0.7px] uppercase text-fg-faint mb-2\">\n145\t        {label}\n146\t      </div>\n147\t      <div className=\"grid gap-1.5\">{children}</div>\n148\t    </div>\n149\t  )\n150\t}\n151\t\n152\texport function DetailLine({ k, v, wrap }: { k: string; v: string; wrap?: boolean }) {\n153\t  return (\n154\t    <div className=\"flex gap-2 font-mono text-xs leading-relaxed\">\n155\t      <span className=\"text-fg-faint shrink-0 w-14\">{k}</span>\n156\t      <span className={`text-fg ${wrap ? 'break-all' : ''}`}>{v}</span>\n157\t    </div>\n158\t  )\n159\t}\n160\t\n161\t// ─── LegendItem — dot + count + label chip used in window strip ──────────────\n162\texport function LegendItem({ dotClass, n, label }: { dotClass: string; n: number; label: string }) {\n163\t  return (\n164\t    <span className=\"inline-flex items-center gap-1.5 text-[13px] text-fg-dim\">\n165\t      <span className={`w-2 h-2 rounded-full ${dotClass}`} aria-hidden=\"true\" />\n166\t      <strong className=\"text-fg font-mono text-[13.5px]\">{n}</strong>\n167\t      {' '}{label}\n168\t    </span>\n169\t  )\n170\t}\n171\t\n172\t// ─── VERDICT_LABELS — verifier verdict → human-readable label ───────────────\n173\t// Single source consumed by the Queue job detail panel, PRDs needs_review\n174\t// card, and History job detail panel — all three surfaces display a job's\n175\t// verifierVerdict and must show the same human-readable text, not the raw\n176\t// machine slug (e.g. \"no_verdict_sentinel\").\n177\texport const VERDICT_LABELS: Record<string, string> = {\n178\t  halt: 'verifier halted',\n179\t  deps_unmet: 'dependencies unmet',\n180\t  transcript_errors: 'transcript had errors',\n181\t  verify_unavailable: 'verify unavailable',\n182\t  uncommitted_changes: 'uncommitted changes',\n183\t  no_verdict_sentinel: 'no commit or verdict sentinel',\n184\t  pass_no_commit: 'PASS sentinel but no commit landed',\n185\t}\n186\t\n187\texport function verdictLabel(verdict: string): string {\n188\t  return VERDICT_LABELS[verdict] ?? verdict\n189\t}\n190\t\n191\t// ─── prdNumber — extract leading numeric group from a slug ──────────────────\n192\texport function prdNumber(slug: string): string | null {\n193\t  const m = slug.match(/^(\\d+)-/)\n194\t  return m ? m[1] : null\n195\t}\n196\t\n197\t// ─── PrdNumberBadge — monospaced #NN chip (Almanac design) ──────────────────\n198\texport function PrdNumberBadge({ n }: { n: string }) {\n199\t  return (\n200\t    <span\n201\t      className=\"font-mono text-[12px] font-semibold text-fg-faint shrink-0 tracking-tight select-none\"\n202\t      aria-hidden=\"true\"\n203\t    >\n204\t      #{n}\n205\t    </span>\n206\t  )\n207\t}\n208\t\n209\t// ─── STATUS_TONE — PRD status pill styling ───────────────────────────────────\n210\t// Consumed by SchedulerPrdsView restyle (PRD 20-scheduler-prds).\n\n... [46 lines truncated] ..."},"type":"attachment","uuid":"06aee7a1-1188-48f2-a391-193bb64fba7b","timestamp":"2026-08-01T05:50:49.167Z","session_id":"c8d2ca66-6317-4c69-9461-dbbdad3aee58","userType":"external","entrypoint":"cli","cwd":"/home/bilko/Projects/session-manager","sessionId":"c8d2ca66-6317-4c69-9461-dbbdad3aee58","version":"2.1.220","gitBranch":"main"}
