se };\n    }\n\n    if (reuseByGoal) {\n      for (const s of Object.values(index.sessions)) {\n        if (s && s.status === 'active' && s.goalText === goalText) {\n          const prdDir = resolveEpicPrdWriteDir(cwd, s.id);\n          fs.mkdirSync(prdDir, { recursive: true });\n          return { epicId: s.id, prdDir, created: false };\n        }\n      }\n    }\n\n    const epicId = `${slugify(goalText)}-${crypto.randomUUID().slice(0, 8)}`;\n    const now = new Date().toISOString();\n    const session = {\n      id: epicId,\n      cwd,\n      goalText: String(goalText || ''),\n      // Independently minted, never shared with a SessionTab — same invariant\n      // as renderer-created PromptSessions (state/promptSessions.ts).\n      claudeSessionId: crypto.randomUUID(),\n      status: 'active',\n      createdAt: now,\n      completedAt: null,\n      ...(tag ? { tag } : {}),\n    };\n    const firstEvent = {\n      id: crypto.randomUUID(),\n      promptSessionId: epicId,\n      kind: 'prompt',\n      causedByEventId: null,\n      at: now,\n      text: String(goalText || ''),\n    };\n    index.sessions[epicId] = session;\n    index.events[epicId] = [firstEvent];\n    writeActiveIndex(cwd, index);\n\n    const prdDir = resolveEpicPrdWriteDir(cwd, epicId);\n    fs.mkdirSync(prdDir, { recursive: true });\n    return { epicId, prdDir, created: true };","is_error":false}]},"uuid":"f662583a-b49c-4131-805d-13f41292561c","timestamp":"2026-08-01T06:02:43.591Z","toolUseResult":{"stdout":"    // before this hook's own run-verify/self-heal passes might touch the same\n    // (slug, runId) again. Once archived, the live-dir check alone goes false\n    // and a re-trigger would refile a duplicate straight into the live inbox.\n    const processedPath = path.resolve(path.join(dest.dir, 'processed', fileName));\n    if (!processedPath.startsWith(path.resolve(path.join(dest.dir, 'processed')) + path.sep)) {\n      console.log(`[rca] skip: processedPath escaped processed dir (${proc